// =====================================================================================
// Conjunto próprio de ícones do NKote (categorias e contas), ADR 0018.
//
// Os desenhos são os caminhos do Material Icons (licença Apache 2.0, © Google), copiados
// só para os ícones que o app usa. Assim o APK não precisa do pacote "extended" inteiro.
// O banco guarda só o NOME do ícone (ex.: "carrinho"); esta tabela traduz o nome no desenho.
// =====================================================================================

private fun icone(nome: String, vararg caminhos: String): ImageVector =
    ImageVector.Builder(name = nome, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f)
        .apply { for (c in caminhos) addPath(pathData = addPathNodes(c), fill = SolidColor(Color.Black)) }
        .build()

/** Um ícone escolhível: o nome gravado no banco, o rótulo para leitores de tela e o desenho. */
class IconeNk(val nome: String, val rotulo: String, desenho: () -> ImageVector) {
    val vetor: ImageVector by lazy(desenho)
}

