    private val porNome = todos.associateBy { it.nome }

    /** O desenho de um nome gravado no banco. Nome desconhecido (ou vazio) vira "outros". */
    fun de(nome: String?): ImageVector = (nome?.let { porNome[it] } ?: porNome.getValue("outros")).vetor

    fun existe(nome: String?): Boolean = nome != null && nome in porNome
